    const nav = ul.querySelector(':scope > li.boardNavTop');
    nbHere = { kind: 'board', board: id, next, more: next, bn: reClean((nav && nav.querySelector('h1')) ? nav.querySelector('h1').textContent : '') };
    nbHalfSet(nbHalfOf(location.href));
    if (nav) nbBoardHead(nav, id);
    const seen = nbSeen(), me = nbMe(), rows = [...ul.querySelectorAll(':scope > li:not(.boardNavTop)')];
    for (const li of rows) nbRow(li, seen, me);
    nbHere.rs = new Map(rows.map((li) => [li.dataset.topic, li.dataset.r]));
    if (nbCapSeen(id, nbPageNo(next), nbRowIds(document), document)) nbFirstNote(nbPageNo(next), nbPageNo(next) - 1);   // (how far back it goes: learnt here)
    nbLearn(rows);
