    if (s && s.me) { const y = document.createElement('span'); y.className = 'bnp-nbin'; y.setAttribute('data-bnp', 'nbin'); y.textContent = 'you posted'; y.title = 'You’ve posted in this topic'; title.append(y); }
    const mk = document.createElement('button');
