    const parts = (root) => ({ v: [...root.querySelectorAll(':scope > div')].find((d) => /Viewing:/.test(d.textContent)), form: root.querySelector(':scope > form[name="messages"]'), pagers: [...root.querySelectorAll(':scope > table')].filter((t) => t.querySelector('a[href*="lower="]') || !t.querySelector('form, input')) });
    const a = parts(tc), b = parts(ntc);
    if (!a.form || !b.form) return false;
    if (a.v && b.v) a.v.replaceWith(document.importNode(b.v, true));
