    let list = p.list;
    if (how === 'type') list = list.map((u, i) => [u, i]).filter(([u]) => u.includes(q) && u !== q).sort((a, b) => (b[0].startsWith(q) - a[0].startsWith(q)) || a[1] - b[1]).map(([u]) => u);
    w.list = list.slice(0, how === 'all' ? 80 : 6);
