  function nclSmPaint(open, keep) {   // (the smilies picker, over where you write: the boards' own, a click puts one in. Its smilies scroll under its tabs, clear of its round corners. keep: where you were in the list kept)
    const box = ncl && ncl.el.querySelector('[data-ncl-sm]'), btn = ncl && ncl.el.querySelector('[data-ncl="smilies"]');
    if (!box) return;
    if (open !== undefined) { box.hidden = !open; nbSmPicking = false; }
    if (btn) btn.setAttribute('aria-expanded', String(!box.hidden));
    if (box.hidden) return;
    const was = keep ? ((box.querySelector('.bnp-ncl-smlist') || {}).scrollTop || 0) : 0;
    box.innerHTML = nbSmHtml();
    const tabs = box.querySelector('.bnp-nbsm-tabs'), list = document.createElement('div');
    list.className = 'bnp-ncl-smlist';
    while (tabs && tabs.nextSibling) list.append(tabs.nextSibling);
    box.append(list);
    const pb = list.querySelector(':scope > .bnp-nbsm-pickbar');
    if (pb) box.insertBefore(pb, list);   // (choosing's bar under the tabs, never scrolled away)
    if (was) list.scrollTop = was;
    const g = list.querySelector('.bnp-nbsm-grid'), nm = list.querySelector('.bnp-nbsm-name');
    if (g && nm) list.style.maxHeight = `${nm.offsetHeight + 10 + Math.ceil(Math.max(...nbSmCats().map(([, , l]) => l.length)) / getComputedStyle(g).gridTemplateColumns.split(' ').length) * 36}px`;   // (each group as tall as it needs, up to the biggest group's height: no group has a scrollbar; All scrolls)
    const msgs = ncl.el.querySelector('[data-ncl-msgs]'), comp = box.parentElement;   // (a small window: no taller than the conversation it covers)
    box.style.maxHeight = msgs && comp ? `${Math.max(150, Math.round(comp.getBoundingClientRect().top - msgs.getBoundingClientRect().top) - 2)}px` : '';
  }
  function nclFit(ta) {   // (two lines to start with, growing as you write, up to two fifths of the conversation; a size of your own, or the big box: left as it is)
    if (!ta || ta.dataset.manual || (ncl && ncl.el.classList.contains('is-tabig'))) return;
    const chat = ta.closest('[data-ncl-chat]'), cap = Math.max(180, Math.round((chat ? chat.clientHeight : 450) * 0.4));
    ta.style.height = 'auto';
    ta.style.height = `${Math.min(ta.scrollHeight + 4, cap)}px`;
    ta.__fitH = ta.offsetHeight;
  }
  function nclTaBig(on) {   // (the writing box big: most of the conversation's room, its last messages still in sight above; kept for the next time)
    if (!ncl) return;
    ncl.el.classList.toggle('is-tabig', !!on);
    try { if (on) localStorage.setItem('bnp-ncl-tabig', '1'); else localStorage.removeItem('bnp-ncl-tabig'); } catch (_) { /* */ }
    const b = ncl.el.querySelector('[data-ncl="tabig"]'), ta = ncl.el.querySelector('[data-ncl-ta]'), list = ncl.el.querySelector('[data-ncl-msgs]');
    if (b) { b.setAttribute('aria-pressed', String(!!on)); b.title = on ? 'Back to the usual size' : 'A bigger box to write in'; b.setAttribute('aria-label', on ? 'Make the writing box its usual size' : 'Make the writing box bigger'); b.innerHTML = on ? NCL_SVG.unmax : NCL_SVG.max; }
    if (ta) { delete ta.dataset.manual; nclFit(ta); ta.focus(); }
    if (list && ncl.stick) list.scrollTop = list.scrollHeight;   // (its newest message in sight, as it was)
  }
  function nclLookNow() {   // (Look now, pressed: a look at once, then 10 seconds before it can be pressed again)
    if (nclBusy || Date.now() < nclCool) return;
    nclCool = Date.now() + 10000;
    if (Date.now() - Number(get('nclChk', 0)) < 10000) {   // (any tab looked in the last 10 seconds: what it found is already here)
      nclPaint();
      nclToast({ kind: 'info', text: 'Up to date: it looked a few seconds ago', ms: 3000 });
      nclCheckPaint();
      setTimeout(nclCheckPaint, 10050);
      return;
    }
    nclLastN = -1;
    nclCheck(true).then((r) => { if (r === 'held') { nclPaint(); nclToast({ kind: 'info', text: 'Up to date: it looked a few seconds ago', ms: 3000 }); return; } if (nclLastN < 0) return; if (nclErr) nclToast({ kind: 'bad', text: nclErr }); else if (!nclLastN) nclToast({ kind: 'info', text: 'No new Neomail', ms: 3000 }); });   // (pressed: a word either way, so you know it looked)
    nclCheckPaint();
    setTimeout(nclCheckPaint, 10050);
  }
  function nclCheckPaint() {   // (every Look now: spinning while it looks; resting, dimmed, after a press)
    const cool = Date.now() < nclCool;
    for (const b of $$('.bnp-ncl [data-ncl="check"], .bnp-ncl-phead [data-ncl-p="check"]')) {
      b.disabled = nclBusy || cool;
      b.classList.toggle('is-spin', nclBusy);
      b.classList.toggle('is-cool', cool && !nclBusy);
      if (b.classList.contains('bnp-ncl-hb')) { b.title = nclBusy ? 'Looking for new Neomail…' : cool ? 'Looked just now (again in a few seconds)' : 'Look for new Neomail now'; b.setAttribute('aria-label', b.title); }
    }
  }
  function nclStatusPaint() {   // (when it last looked; its button says how often it does, and looks now)
    const box = ncl && ncl.el.querySelector('[data-ncl-status]');
    if (!box) return;
    const at = Number(get('nclChk', 0)), ago = nclAgo(at), m = nclEvery(), next = Math.max(0, Math.round((nclDue() - Date.now()) / 60000));
    const said = nclBusy ? 'Reading your Inbox…' : nclErr || (nclAway === 'stop' && m ? 'Paused till you’re back' : at ? `Looked ${ago === 'now' ? 'just now' : `${ago}${/min$/.test(ago) ? ' ago' : ''}`}` : 'Not looked yet');
    const how = !m ? 'It looks only when you ask' : nclAway === 'stop' ? 'You’ve been away from Neopets 4 hours: it looks again when you’re back' : `It looks about every ${nclEveryWords(m)} while NeoChat is open or folded${nclAway === 'slow' ? ', less often while you’re away' : ''}${at ? `: next in about ${next ? nclMins(next) : 'a moment'}` : ''}`;
    box.innerHTML = `<span>${esc(said)}</span><button type="button" class="bnp-pillbtn" data-ncl="check" title="Look for new Neomail now. ${esc(how)} (Settings › NeoChat)">${NCL_SVG.check}${m ? `Every ${nclMins(m)}` : 'Only when asked'}</button>`;
    nclCheckPaint();
  }
  function nclBubPaint() {
    if (!ncl || !ncl.bub) return;
    const n = nclNewCount(), b = ncl.bub.querySelector('[data-ncl-bubn]');
    b.hidden = !n;
    b.textContent = n > 9 ? '9+' : String(n);
    ncl.bub.title = n ? `NeoChat: ${n} with new Neomail` : 'NeoChat';
    ncl.bub.setAttribute('aria-label', n ? `Open NeoChat: ${n} with new Neomail` : 'Open NeoChat');
  }
  async function nclSendNow() {
    if (!ncl || ncl.sending || !ncl.who || NCL_NOREPLY.has(ncl.who)) return;
    const ta = ncl.el.querySelector('[data-ncl-ta]'), sj = ncl.el.querySelector('[data-ncl-subj]'), err = ncl.el.querySelector('[data-ncl-err]'), btn = ncl.el.querySelector('[data-ncl="send"]');
    if (!ta) return;
    const who = ncl.who, body = ta.value, d = nclData(), to = (d.p[who] || {}).n || who, subject = sj.value.trim() || 'Hi!';
    if (!body.trim()) { ta.focus(); return; }
    ncl.sending = true;
    btn.disabled = true;
    err.hidden = true;
    ncl.el.classList.add('is-busy');
    let bad = '';
    try { bad = await nmSendNow(to, subject, body); } catch (e) { report(e); bad = 'Neopets didn’t answer, so it may not have gone. Send it again in a moment.'; }
    ncl.sending = false;
    ncl.el.classList.remove('is-busy');
    btn.disabled = false;
    if (bad) { err.innerHTML = `${NCL_SVG.cross}<span>${esc(bad)}</span>`; err.hidden = false; ta.focus(); nclSaid(false); return; }
    const rest = (v) => (v === body ? '' : v.startsWith(body) ? v.slice(body.length).replace(/^[ \t]*\r?\n/, '') : v);   // (what's in the box now, less what was sent)
    const cur = ncl.who === who ? ncl.el.querySelector('[data-ncl-ta]') : null, left = cur ? rest(cur.value) : rest(String(nclDrafts()[who] || ''));
    nclDraftPut(who, left);
    if (cur) { if (!left.trim()) delete cur.dataset.manual; cur.value = left; nclFit(cur); }
    nclKeepSent(to, subject, body);
    const rec = nbJson(acctKey(NMW_TO), []);   // (written to lately: first in the little window's To)
    nbJsonSet(acctKey(NMW_TO), [who, ...(Array.isArray(rec) ? rec : []).filter((x) => x !== who)].slice(0, 20));
    ncl.stick = true;
    nclPaint();
    nclSaid(true);
    const now = ncl.el.querySelector('[data-ncl-ta]');
    if (now && ncl.who === who) now.focus();
  }
  function nclClick(e) {
    const t = e.target instanceof Element ? e.target : null;
    if (!t) return;
    const tab = t.closest('[data-ncl-tab]');
    if (tab) { nclTabSet(tab.dataset.nclTab); return; }
    const who = t.closest('[data-ncl-who]');
    if (who) { ncl.jump = who.dataset.nclMid || ''; if (ncl.sent) ncl.sentMid = ncl.jump; nclWho(who.dataset.nclWho, !!ncl.jump); return; }   // (a message found, or one you've sent: its conversation, at it)
    const sm = t.closest('[data-nbsm], [data-nbsmcat], [data-nbsmpick]');
    if (sm && ncl.el.contains(sm)) {   // (the smilies picker: a group, or one put in where you were writing; or your favourites chosen)
      if (sm.dataset.nbsmpick != null) { nbSmPicking = !nbSmPicking; nclSmPaint(undefined, true); return; }
      if (sm.dataset.nbsmcat != null) { nbSmCat = Number(sm.dataset.nbsmcat); nbJsonSet('bnp-nbsmall', nbSmCat === -1 ? 1 : 0); nclSmPaint(); return; }
      if (nbSmPicking && sm.dataset.nbsm) { nbSmFavToggle(sm.dataset.nbsm); nclSmPaint(undefined, true); return; }
      const ta = ncl.el.querySelector('[data-ncl-ta]'), code = sm.dataset.nbsm;
      if (!ta || !code) return;
      const a = ta.selectionStart ?? ta.value.length, z = ta.selectionEnd ?? a, v = ta.value;
      ta.value = v.slice(0, a) + code + v.slice(z);
      ta.focus();
      ta.setSelectionRange(a + code.length, a + code.length);
      nclDraftPut(ncl.who, ta.value);
      nclFit(ta);
      nbSmUsed(code);
      return;
    }
    const b = t.closest('[data-ncl]');
    if (!b) return;
    const k = b.dataset.ncl;
    if (k === 'smilies') { const box = ncl.el.querySelector('[data-ncl-sm]'); nclSnipsPaint(false); nclSmPaint(!!(box && box.hidden)); return; }
    if (k === 'check') nclLookNow();
    else if (k === 'home') nclHome();
    else if (k === 'back') nclBack();
    else if (k === 'actsfold') { const off = nclKept('bnp-ncl-actsoff', '') === '1'; try { if (off) localStorage.removeItem('bnp-ncl-actsoff'); else localStorage.setItem('bnp-ncl-actsoff', '1'); } catch (_) { /* */ } nclChatPaint(); const f = ncl.el.querySelector('[data-ncl="actsfold"]'); if (f) f.focus(); }
    else if (k === 'arch') nclArchView(!ncl.arch);
    else if (k === 'archout') nclArchView(false);
    else if (k === 'sent') nclSentView(!ncl.sent);
    else if (k === 'sentout') nclSentView(false);
    else if (k === 'sentmore') { ncl.sentN = (ncl.sentN || 60) + 60; nclListPaint(); }
    else if (k === 'archive') nclArchSet(ncl.who, true);
    else if (k === 'unarchive') nclArchSet(ncl.who, false);
    else if (k === 'min') nclMin();
    else if (k === 'x') { if (S.features.nclXFold) nclMin(); else nclClose(); }   // (Close folds it, if you've chosen that: back to its round button)
    else if (k === 'send') nclSendNow();
    else if (k === 'tabig') nclTaBig(!ncl.el.classList.contains('is-tabig'));
    else if (k === 'max') nclMaxSet(!ncl.el.classList.contains('is-max'), true);
    else if (k === 'set') openHub('neochat');
    else if (k === 'theme') openHub('nclthemes');
    else if (k === 'pin') nclPinSet(!S.features.nclPin);
    else if (k === 'friends') { b.disabled = true; b.textContent = 'Reading them…'; nclFriendsMaybe(true); }
    else if (k === 'nfadd') nclNfAsk();
    else if (k === 'erase') nclEraseAsk();
    else if (k === 'eraseyes') nclErase();
    else if (k === 'readall') nclReadAll();
    else if (k === 'nfyes') nclNfAdd();
    else if (k === 'nfno') { const a = b.closest('[data-ncl-ask]'); if (a) a.remove(); }
    else if (k === 'page') nclState('');   // (its own page instead: the window not brought back there)
    else if (k === 'snips') { const box = ncl.el.querySelector('[data-ncl-snips]'); nclSmPaint(false); nclSnipsPaint(!!(box && box.hidden)); }
    else if (k === 'snipuse') {
      const s = nclSnips()[Number(b.dataset.i)], ta = ncl.el.querySelector('[data-ncl-ta]');
      if (s == null || !ta) return;
      const a = ta.selectionStart ?? ta.value.length, z = ta.selectionEnd ?? a;
      ta.value = ta.value.slice(0, a) + s + ta.value.slice(z);
      ta.setSelectionRange(a + s.length, a + s.length);
      nclDraftPut(ncl.who, ta.value);
      nclFit(ta);
      nclSnipsPaint(false);
      ta.focus();
    }
    else if (k === 'snipdel') { const i = Number(b.dataset.i), list = nclSnips().slice(), [gone] = list.splice(i, 1); S.nclSnips = list; saveNow(); nclSnipsPaint(); nclToast({ kind: 'info', text: 'Quick reply taken away', act: ['Undo', () => { const l = nclSnips().slice(); l.splice(i, 0, gone); S.nclSnips = l; saveNow(); nclSnipsPaint(); }], ms: 6000 }); }
    else if (k === 'snipset') { nclSnipsPaint(false); openHub('neochat'); const c = hub && hub.main.querySelector('[data-g="nclqr"]'); if (c) { c.scrollIntoView({ block: 'start' }); const nw = c.querySelector('[data-nclqr-new]'); if (nw && !nw.disabled) nw.focus({ preventScroll: true }); } }
    else if (k === 'snipadd') { const ta = ncl.el.querySelector('[data-ncl-ta]'), v = ta ? ta.value.trim().slice(0, 1000) : ''; if (!v) return; if (!nclSnips().includes(v)) { S.nclSnips = [...nclSnips(), v].slice(-30); saveNow(); } nclSnipsPaint(); nclToast({ kind: 'ok', text: 'Saved as a quick reply', ms: 3000 }); }
  }
  // The archive: conversations out of your Chats, under the hourglass at the top (p.arch: when it went in). One comes back out by
  // itself when there's a new Neomail in it, from them or from you. Archive by itself (S.features.nclArch, days): conversations with
  // nothing new for that long go in at each look, never one with Neomail you haven't read; one you've taken out (p.back) waits that long again
  function nclArchView(on) {   // (the side: the archive, or your Chats again)
    if (!ncl) return;
    ncl.arch = !!on;
    if (ncl.arch) { nclHomeSet(false); ncl.sent = false; }
    if (ncl.arch && ncl.who && !((nclData().p[ncl.who] || {}).arch)) { ncl.who = ''; try { localStorage.removeItem(acctKey('bnp-ncl-who')); } catch (_) { /* */ } }   // (one from your Chats was open: the archive's own start instead)
    nclPaint();
    const list = ncl.el.querySelector('[data-ncl-list]');
    if (list) list.scrollTop = 0;
  }
  function nclSentView(on) {   // (the side: what you've sent, or your Chats again. Whoever's open stays open)
    if (!ncl) return;
    ncl.sent = !!on;
    ncl.sentN = 60;
    ncl.sentMid = '';
    if (ncl.sent) { ncl.arch = false; nclHomeSet(false); }
    nclPaint();
    const list = ncl.el.querySelector('[data-ncl-list]');
    if (list) list.scrollTop = 0;
  }
  function nclArchSet(k, on) {   // (a conversation into the archive, or back out to your Chats: Undo for a while)
    const me = nclMe(), d = nclData(me), p = k && d.p[k];
    if (!p || !ncl) return;
    const was = { arch: p.arch, seen: p.seen, back: p.back }, wasView = ncl.arch;
    if (on) { p.arch = Date.now(); p.seen = Math.max(p.seen || 0, Date.now()); } else { delete p.arch; p.back = Date.now(); }   // (put away: read, too)
    nclPut(me, d);
    if (on && !ncl.arch) { ncl.who = ''; try { localStorage.removeItem(acctKey('bnp-ncl-who')); } catch (_) { /* */ } }   // (put away from your Chats: closed with it)
    if (!on) ncl.arch = false;   // (taken out: your Chats, still open on it)
    nclPaint();
    try { applyAll(); } catch (_) { /* */ }
    nclToast({ kind: 'info', text: on ? `Your conversation with ${p.n} is in the archive` : `Your conversation with ${p.n} is back in your Chats`, ms: 7000, act: ['Undo', () => {
      const d2 = nclData(me), q = d2.p[k];
      if (!q) return;
      for (const f of ['arch', 'seen', 'back']) { if (was[f]) q[f] = was[f]; else delete q[f]; }
      nclPut(me, d2);
      ncl.arch = wasView;
      nclWho(k);
      try { applyAll(); } catch (_) { /* */ }
    }] });
  }
  function nclAutoArch() {   // (Archive by itself: what's had nothing new for as long as you've chosen, put away)
    const days = Number(S.features.nclArch) || 0, me = nclMe();
    if (!days || !me) return;
    const d = nclData(me), cut = Date.now() - days * 864e5, now = Date.now();
    const old = Object.values(d.p).filter((p) => p.m.length && !p.arch && !nclUnread(p) && Math.max(nclLast(p), Number(p.back) || 0) < cut);
    if (!old.length) return;
    for (const p of old) p.arch = now;
    nclPut(me, d);
    if (ncl && ncl.who && old.some((p) => p.n.toLowerCase() === ncl.who) && !ncl.arch) { ncl.who = ''; try { localStorage.removeItem(acctKey('bnp-ncl-who')); } catch (_) { /* */ } }
    if (ncl) nclPaint();
    nclToast({ kind: 'info', text: `${old.length === 1 ? `Your conversation with ${old[0].n}` : `${old.length} conversations`}, with nothing new for ${days} days, ${old.length === 1 ? 'is' : 'are'} in the archive now`, ms: 7000 });
  }
  function nclBack() {   // (a conversation's ‹: the list it came from, as it was)
    if (!ncl) return;
    ncl.who = '';
    try { localStorage.removeItem(acctKey('bnp-ncl-who')); } catch (_) { /* */ }
    nclPaint();
  }
  function nclHomeCard() {   // (Home's own screen: beside the list in a wide window; pinned or narrow, in its place)
    return `<div class="bnp-ncl-empty"><span class="bnp-ncl-ic">${NCL_SVG.chat}</span><b>Your Neomail, as conversations</b><p>Choose someone in your Chats or Neofriends, or type a username in Find to write to someone new.</p></div>`;
  }
  function nclSentCard() {   // (Sent, with nothing open: what it is, and Neomail's own Sent folder)
    return `<div class="bnp-ncl-empty"><span class="bnp-ncl-ic">${NCL_SVG.send}</span><b>Sent</b><p>What you’ve sent, newest first: from here, from Neopets’ Write a Neomail page and from the little window. Choose one to see it in its conversation.</p>${S.features.nmSent ? `<a class="bnp-pillbtn" href="${NM_SENT_PAGE}">Neomail’s Sent folder</a>` : ''}</div>`;
  }
  function nclHomeSet(on) {   // (Home pressed, or left: by a tab, Find, a conversation or the archive. Kept for the next page, as the conversation open is)
    if (!ncl) return;
    ncl.home = !!on;
    try { if (ncl.home) localStorage.setItem(acctKey('bnp-ncl-home'), '1'); else localStorage.removeItem(acctKey('bnp-ncl-home')); } catch (_) { /* */ }
    ncl.el.classList.toggle('is-home', ncl.home);
  }
  function nclHome() {   // (Home: your Chats, from wherever you are (your Neofriends, the archive, a search, a conversation); pinned or narrow, Home's own screen with Chats and Neofriends over it)
    if (!ncl) return;
    ncl.who = '';
    ncl.arch = false;
    ncl.sent = false;
    try { localStorage.removeItem(acctKey('bnp-ncl-who')); } catch (_) { /* */ }
    if (ncl.q) { ncl.q = ''; const q = ncl.el.querySelector('[data-ncl-q]'); if (q) q.value = ''; }
    if (ncl.tab !== 'chats') nclTabSet('chats');
    nclHomeSet(true);
    nclPaint();
    const list = ncl.el.querySelector('[data-ncl-list]');
    if (list) list.scrollTop = 0;
  }
  function nclSettingsChanged(k) {   // (one of NeoChat's settings changed: at once, on this page)
    if (k === 'ncl' && !S.features.ncl) { nclTickOff(); if (ncl && !ncl.page) { ncl.el.classList.remove('open', 'is-min'); ncl.bub.hidden = true; } return; }
    if ((k === 'ncl' || k === 'nclAlways') && S.features.ncl && S.features.nclAlways && nclState() !== 'x' && !(ncl && (nclIsOpen() || !ncl.bub.hidden))) nclFold();
    if ((k === 'nclSound' || k === 'nclVol') && S.features.nclSound) remSound(S.features.nclSound, nclVol());   // (heard as it's picked, and at its new loudness)
    nclHbHoverPaint();
    if (!ncl) return;
    if (k === 'nclEnter') { const c = ncl.el.querySelector('[data-ncl-chat]'); if (c) c.dataset.who = ''; }   // (its hint about Enter, written again)
    if (k === 'nclArch') nclAutoArch();   // (chosen: put away now what's waited that long)
    if (k === 'nclPinSide') nclPinPaint(true);
    if (k === 'nclDim') nclDimPaint();
    nclPaint();
  }
  function nclBoot() {   // (the page read: the window back as it was on this tab's last page (folded on every page, if you've chosen that and haven't closed it here); or this is its own page. Then Neopets' own alerts)
    if (nclSentKeep()) nclPendCheck();   // (a Neomail sent from Neopets' own page just now: kept, for NeoChat and the Sent folder)
    if (!S.features.ncl) return;
    nclHbHoverPaint();
    nclMe();
    if (nclHere()) nclPageMake();
    else {
      const st = nclState();
      if (st === 'open' || (!st && S.features.nclPin)) nclOpen({ quiet: true });   // (pinned: at its side on every page, unless you've folded or closed it in this tab)
      else if (st === 'min' || (!st && S.features.nclAlways)) nclFold();
    }
    nclPinPaint();
    nclAlertsWatch();
    document.addEventListener('visibilitychange', () => { if (!document.hidden && ncl && ncl.who && nclIsOpen()) nclPaint(); });   // (back on this tab: what came while it was out of sight, seen now)
  }
  function nclPageMake() {   // (its own page: Neopets' Neomail page, NeoChat in its place)
    const tc = $('td.content') || $('#container__2020');
    if (!tc || tc.querySelector('[data-bnp="ncl"]')) return;
    for (const n of [...tc.childNodes]) {   // (Neomail's own tabs stay; the rest, Neopets' notes too, put away)
      if (n.nodeType === 3 && n.nodeValue.trim()) { const sp = document.createElement('span'); sp.hidden = true; n.replaceWith(sp); sp.append(n); }
      else if (n.nodeType === 1 && !n.matches('[data-bnp="nmhead"]')) n.hidden = true;
    }
    document.title = 'NeoChat | Neopets';
    const head = document.createElement('div');
    head.className = 'bnp-ncl-phead';
    head.setAttribute('data-bnp', 'nclphead');
    head.innerHTML = `<span class="bnp-ncl-ic">${NCL_SVG.chat}</span><h2>NeoChat</h2><span class="bnp-note">Your Neomail as conversations.</span><span class="bnp-ncl-hbtns"><button type="button" class="bnp-pillbtn" data-ncl-p="home" title="NeoChat’s start (no conversation open)">${NCL_SVG.home}Home</button><button type="button" class="bnp-pillbtn" data-ncl-p="check">${NCL_SVG.check}Look now</button><button type="button" class="bnp-pillbtn" data-ncl-p="arch" aria-pressed="false">${NCL_SVG.arch}Archived</button><button type="button" class="bnp-pillbtn" data-ncl-p="sent" aria-pressed="false">${NCL_SVG.send}Sent</button><button type="button" class="bnp-pillbtn" data-ncl-p="max" aria-pressed="false">${NCL_SVG.max}Full screen</button><button type="button" class="bnp-pillbtn" data-ncl-p="set">${NCL_SVG.gear}Settings</button></span>`;
    head.addEventListener('click', (e) => { const b = e.target instanceof Element && e.target.closest('[data-ncl-p]'); if (!b) return; if (b.dataset.nclP === 'check') nclLookNow(); else if (b.dataset.nclP === 'home') nclHome(); else if (b.dataset.nclP === 'arch') nclArchView(!ncl.arch); else if (b.dataset.nclP === 'sent') nclSentView(!ncl.sent); else if (b.dataset.nclP === 'max') nclMaxSet(!ncl.el.classList.contains('is-max'), true); else openHub('neochat'); });
    tc.append(head, nclBuild(true));
    nclLook(head);
    if (nclKept('bnp-ncl-pmax', '') === '1') nclMaxSet(true);
    nclPaint();
    nclTickOn();
    nclCheck(false);
    nclFriendsMaybe();
    nclMyAvFresh();
    const w = new URLSearchParams(location.search).get('ncuser');
    if (w) nclWho(w, true);
  }
  function nclHubPage() {   // (Settings › NeoChat)
    const f = S.features, d = nclData(), convs = Object.values(d.p).filter((p) => p.m.length), msgs = convs.reduce((n, p) => n + p.m.length, 0);
    const sw = (k, title, small) => `<label class="bnp-switch"><input type="checkbox" data-feat="${k}"${f[k] ? ' checked' : ''}><span>${title}<small>${small}</small></span></label>`;
    const seg = (k, label, list, now) => `<div class="bnp-f bnp-nclseg"><span>${label}</span><span class="bnp-seg" role="group" aria-label="${label}">${list.map(([v, l]) => `<button type="button" data-featv="${k}:${v}" aria-pressed="${now === v}">${l}</button>`).join('')}</span></div>`;
    return `<div class="bnp-mhead"><h2>NeoChat</h2><span class="bnp-note">Your Neomail as conversations, in your theme: a window over any page (full screen if you like, or folded to a round button), or a page of its own.</span></div>
      <div class="bnp-card">
        ${sw('ncl', 'NeoChat', 'Community › NeoChat opens it. Chats: who you’ve heard from and written to, newest first. Neofriends: yours, online first, to start one. Each conversation as the boards show posts; Enter sends it as a Neomail, as Neopets’ own page does.')}
        ${f.ncl ? `<div class="bnp-tools"><button type="button" class="bnp-pillbtn is-go" data-nclset="open">Open it</button><a class="bnp-pillbtn" href="${NCL_PAGE}">Its own page</a><button type="button" class="bnp-pillbtn" data-nclset="looks">Its look: NeoChat Themes</button></div>` : ''}
      </div>
      <div class="bnp-card"><h4>Looking for new Neomail</h4>
        ${seg('nclEvery', 'How often', NCL_EVERY, String(nclEvery()))}
        ${(() => { const m = nclEvery(); return `<div class="bnp-nclhow"><i class="bnp-bang" aria-hidden="true">!</i><ul aria-label="How it looks">${m ? `<li>About every ${nclEveryWords(m)}, a little sooner or later each time</li>
          <li>${f.nclAlways ? 'In every tab, from its round button in the corner' : 'Only in tabs where NeoChat is open or folded'}</li>
          <li>Away from Neopets: less and less often, none after 4 hours, back to normal when you return</li>
          <li>With several tabs, only the one you’re on looks</li>` : '<li>Only when you press Look now</li>'}
          <li>A Neomail it reads is marked read, as on Neopets</li></ul></div>`; })()}
        ${sw('nclAlways', 'Round button in every tab', 'Every Neopets tab starts with NeoChat folded into a round button in the corner, so new Neomail is found wherever you are. Off: NeoChat only shows up, and only looks, in tabs where you open it. Its × hides it in that tab alone.')}
      </div>
      <div class="bnp-card"><h4>When new Neomail comes</h4>
        ${sw('nclSay', 'An alert on the page', 'Who it’s from and how it starts, with Read to open it (not for a conversation you’re reading). Gone in a few seconds.')}
        ${seg('nclSound', 'A sound', NCL_SOUNDS, f.nclSound || '')}
        <label class="bnp-f bnp-nclvol"><span>How loud</span><input type="range" min="5" max="100" step="5" data-feat="nclVol" value="${Math.round(nclVol() * 100)}" aria-label="How loud the sound is"><output>${Math.round(nclVol() * 100)}%</output></label>
        <p class="bnp-note">Each one plays as you pick it, and again when you let go of How loud.</p>
        ${sw('nclDesk', 'A desktop notice', 'While you’re in another tab or window: who it’s from and how it starts. Click it for NeoChat.')}
        ${sw('nclPop', 'NeoChat opens on it', 'Folded, it opens on their conversation, in the tab you’re looking at (never taking your typing away from where it is).')}
        <label class="bnp-switch"><input type="checkbox" data-nclteam${nclMuted().has('theneopetsteam') ? ' checked' : ''}><span>Quiet for The Neopets Team<small>Their Neomail — gifts and NC items sent to you, and Neopets’ other notices — still comes into NeoChat and your Inbox, just with no alert, sound, desktop notice or count.</small></span></label>
      </div>
      <div class="bnp-card"><h4>Writing and opening</h4>
        ${(() => { const now = f.nclEnter === 'ctrl' || f.nclEnter === 'button' ? f.nclEnter : 'enter'; return `${seg('nclEnter', 'Sending', [['enter', 'Enter sends'], ['ctrl', 'Ctrl+Enter sends'], ['button', 'Only the Send button']], now)}
        <p class="bnp-note">${now === 'enter' ? 'Shift+Enter makes a new line.' : 'Enter makes a new line.'}</p>`; })()}
        ${seg('nclMenu', 'NeoChat in the menu opens', [['win', 'Its window'], ['page', 'Its own page']], f.nclMenu === 'page' ? 'page' : 'win')}
        <p class="bnp-note">A Ctrl-click or a middle click on it opens its own page in a new tab.</p>
      </div>
      <div class="bnp-card"><h4>Muted</h4>
        ${(() => { const mu = [...nclMuted()]; return `<p class="bnp-note bnp-cardlead">Their Neomail still comes into NeoChat and your Inbox, quietly: no alert, sound, desktop notice or count.</p>
        <div class="bnp-f"><span>Mute someone</span><input type="text" class="bnp-inline" data-g="nclmutewho" placeholder="Their username" maxlength="20" spellcheck="false" autocomplete="off" aria-label="Their username, to mute them"><button type="button" class="bnp-linkbtn" data-nclset="muteadd">Mute</button></div>
        <div class="bnp-f"><span>Muted</span>${mu.length ? `<span class="bnp-chips is-static">${mu.map((k) => `<span class="bnp-chip">${esc(nclWhoName(k))}<button type="button" class="bnp-chip-x" data-nclset="unmute" data-k="${esc(k)}" title="Unmute" aria-label="Unmute ${esc(nclWhoName(k))}">×</button></span>`).join('')}</span>` : '<span class="bnp-note">No one</span>'}</div>
`; })()}
      </div>
      <div class="bnp-card" data-g="nclqr"><h4>Quick replies</h4>${nclQrCard()}</div>
      <div class="bnp-card"><h4>Its window</h4>
        <p class="bnp-note bnp-cardlead">Its header’s buttons: click one to show it or hide it there. Close always stays: ${f.nclXFold ? 'it folds NeoChat into its round button (Close folds it, below)' : 'it puts NeoChat away in that tab (with its round button in every tab, your other tabs keep it)'}, so Fold can go.</p>
        ${nclHbPick()}
        ${sw('nclHbHover', 'Its buttons only when you point at its header', 'A clean header: they show as you point at the header itself (not the conversation under it), and while you use them with the keyboard. On a touch screen they always show.')}
        ${sw('nclXFold', 'Close folds it', 'Its × folds NeoChat into its round button in the corner, as Esc does, instead of putting it away in that tab. It keeps looking for new Neomail.')}
        ${sw('nclOutFold', 'A click outside it folds it', 'A click on the page around its window folds NeoChat into its round button in the corner, so the page is yours again. It keeps looking for new Neomail. Never while it’s pinned or full screen.')}
        ${seg('nclPinSide', 'Pinned, it sits', [['right', 'On the right'], ['left', 'On the left']], f.nclPinSide === 'left' ? 'left' : 'right')}
        <p class="bnp-note">The pin in its header keeps NeoChat at that side of every page, under the top bar, with the page beside it (folded or closed in a tab, it stays that way there). Drag its edge to make it wider or narrower; drag the window’s corner to size it when it isn’t pinned.</p>
        <div class="bnp-tools"><button type="button" class="bnp-pillbtn" data-nclset="size"${nclSized() ? '' : ' disabled'}>Back to its first size</button><span class="bnp-note">${nclSized() ? 'Its size, its place and its pinned width, as it started.' : 'It’s the size it started at.'} A double-click on its corner (or, pinned, its edge) does the same.</span></div>
        ${seg('nclDim', 'The page behind its window', [['', 'As it is'], ['dark', 'Darker'], ['blur', 'Blurred'], ['both', 'Both']], f.nclDim || '')}
        <p class="bnp-note">Never while it’s pinned (the page is beside it then), or full screen. With one on, a click on the page folds NeoChat.</p>
      </div>
      <div class="bnp-card"><h4>The archive</h4>
        <p class="bnp-note bnp-cardlead">Conversations put away, out of your Chats: the hourglass at the top shows them, and the one by a conversation’s name puts it there. A new Neomail in one, from them or from you, brings it back.</p>
        ${seg('nclArch', 'Archive by itself', [['0', 'Off'], ['3', 'After 3 days'], ['7', '7 days'], ['14', '14 days'], ['30', '30 days'], ['60', '60 days'], ['90', '90 days']], String(Number(f.nclArch) || 0))}
        <p class="bnp-note">With nothing new for that long, at each look. Never one with Neomail you haven’t read.</p>
      </div>
      <div class="bnp-card"><h4>Avatars</h4>
        ${seg('nclAvList', 'In the list of chats', [['full', 'Their own size'], ['half', 'Half size']], f.nclAvList === 'half' ? 'half' : 'full')}
        ${seg('nclAvChat', 'In conversations', [['full', 'Their own size'], ['half', 'Half size']], f.nclAvChat === 'half' ? 'half' : 'full')}
        <p class="bnp-note">Half size: 25 by 25, still whole in their frames. More of the list, or of what’s written, fits.</p>
        <h5>Your Neofriends’ avatars</h5>
        <div class="bnp-nfload" data-g="nfload">${nfLoadHtml()}</div>
      </div>
      <div class="bnp-card"><h4>What it keeps <span class="bnp-note">${convs.length ? `${convs.length} ${convs.length === 1 ? 'conversation' : 'conversations'}, ${msgs} ${msgs === 1 ? 'message' : 'messages'}` : ''}</span></h4>
        <p class="bnp-note bnp-cardlead">In this browser, for each of your accounts: the newest 150 conversations, each its newest 150 messages. Your Neomail itself stays on Neopets.</p>
        <div class="bnp-tools"><button type="button" class="bnp-pillbtn is-danger" data-nclset="forget">Forget what it’s kept</button></div>
        <p class="bnp-note">Back up (in Enhance) keeps NeoChat’s conversations too, and Restore adds them back, nothing here lost.</p>
      </div>`;
  }


