      if (!on || (!v[k] && !v[on])) continue;
      const a = hexA(nctResolve(k))[0], b = hexA(nctResolve(on))[0];
      if (!a || !b) continue;
      const [l1, l2] = [lum(a), lum(b)].sort((x, y) => y - x), r = (l1 + 0.05) / (l2 + 0.05);
