        const q = new URLSearchParams([...k.cats.map((c) => ['category[]', c]), ...(k.rarity ? [['rarity[]', String(k.rarity[0])], ['rarity[]', String(k.rarity[1])]] : []), ['limit', '3000'], ['page', String(page)], ['intent', 'card'], ['includeStats', 'true']]);
