  const MALL_SORTS = [['kind', 'By kind, newest first'], ['mall', 'The Mall’s order'], ['new', 'Newest first'], ['old', 'Oldest first'], ['leaving', 'Leaving soonest'], ['hi', 'Price: highest first'], ['lo', 'Price: lowest first'], ['az', 'Name: A to Z'], ['za', 'Name: Z to A']];
