    if (id > mallNewest.id) { mallNewest = { id, at: Date.now() }; clearTimeout(mallNewestSeen.t); mallNewestSeen.t = setTimeout(() => { try { localStorage.setItem(MALL_NEWEST, JSON.stringify(mallNewest)); } catch (_) { /* */ } }, 1500); }
