    if (S.features.ncMallNewFill === false || !own.length) return;
    const now = Date.now() / 1000, from = Math.min(...own.map((x) => x.begin || now)), ownFams = new Set(own.map((x) => mallFam(x.name)));
    const gone = get(MALL_NEW_GONE, null) || {}, want = new Map();
