    const out = [], rx = /(\d+)\s*:\s*\{\s*name\s*:\s*"((?:[^"\\]|\\.)*)"\s*,\s*image\s*:\s*"(?:[^"\\]|\\.)*"\s*,\s*end\s*:\s*"(\d{1,2}\/\d{1,2})"/g;
