          try { navigator.clipboard.writeText(lines.join('\n')).then(done, () => { clo.note = 'Your browser didn’t let the list be copied.'; cloPaint(true); }); } catch (_) { clo.note = 'Your browser didn’t let the list be copied.'; cloPaint(true); }
