      say.innerHTML = `${n ? `<b>${n.toLocaleString()}</b> of ${all.toLocaleString()} ranked` : 'None ranked yet: 0 is unranked'}${ch ? ` · <b>${ch.toLocaleString()}</b> change${ch === 1 ? '' : 's'} not saved yet` : ''}`;
