    if (probe && probe !== own) probe.remove();
    try { if (g) localStorage.setItem('bnp-shop-grad', g); else if (own) localStorage.removeItem('bnp-shop-grad'); else g = localStorage.getItem('bnp-shop-grad') || ''; } catch (_) { /* */ }
