        const a = itemEl(d.href, d.label, dailyIcon(d), { kind: 'daily', cls: `bnp-sub bnp-dl is-${show ? st.s : 'ready'}${show && st.s === 'done' ? ' bnp-done' : ''}`, title: `${d.label}: ${stateLong(d, st, now)}`, newTab: S.features.dailyTab });
