        out.push(itemEl(`${base}#bnp-guild=messages`, 'Messages', iconOf(['el:.alerts-tab-item-icon__2020', 'nat:community-neoboards-icon']), sub));
        out.push(itemEl(`/guilds/guild_members.phtml?id=${g.id}`, 'Members', iconOf(['el:.nav-community-icon__2020']), sub));
