      const name = own ? (x ? x.label : '') : (u.h ? (u.h.dataset.bnpOrig != null ? u.h.dataset.bnpOrig : u.h.textContent) : ''), shown = (C.names || {})[u.key] || name, off = !!(C.hide || {})[u.key];
