  const avIcon = () => { const m = S.features.avIcon, r = m === 'rel' ? avRel() : null, f = (m === 'new' && avNewest()) || (r && r.f) || avWorn(); return f ? avPic(f) : AV_DEFAULT_PIC; };   // (the one you wear, your newest, or the newest released)
