      const cur = document.querySelector('#avatar_preview img'), own = avOwn();
      if (cur && own && own.cur !== avFile(cur.getAttribute('src'))) { own.cur = avFile(cur.getAttribute('src')); set('avown', own); }
      if (cur) avSeeMine(cur.getAttribute('src'));
      avSettingsLink();
